    // Construct the API endpoint URL
    const backupUrl = `${API_BASE_URL}/v1/users/${username}/backup`;

    // Set authorization header with API key
    const headers = {
      'Authorization': `Bearer ${apiKey}`,
    };

    // Perform the backup request
    const response = await axios.post(backupUrl, null, { headers });

